declare module "*.html" {
  const content: string;
  export default content;
}
declare module "*.css" {
  const content: string;
  export default content;
}
declare module "*.js" {
  const content: string;
  export default content;
}
declare module "*.json" {
  const content: string;
  export default content;
}
declare module "*.webp" {
  const content: ArrayBuffer;
  export default content;
}
